-- TRACKB seed: pos_accounting_db
BEGIN;
DELETE FROM payment_application_reversal WHERE reversed_by = 'trackb-seed';
DELETE FROM payment_application WHERE application_request_id LIKE 'TRACKB-%';
DELETE FROM receivable_payment WHERE created_by = 'trackb-seed';
DELETE FROM customer_credit_transaction WHERE request_id LIKE 'TRACKB-%';
DELETE FROM customer_credit WHERE created_by = 'trackb-seed';
DELETE FROM credit_memo WHERE created_by_user_id = 'trackb-seed';
DELETE FROM ext_invoice_payment_reversal WHERE refund_id = 'f5aa4bd1-fbb3-57a0-8a6d-4407998a6ee6';
DELETE FROM ext_invoice_deposit_credit_application WHERE application_id = '4df39a52-c78a-596e-8942-8e2a98924635';
DELETE FROM ext_invoice WHERE invoice_number LIKE 'TRACKB-%';
DELETE FROM ap_payment_allocation WHERE payment_id IN (SELECT payment_id FROM ap_payment WHERE payment_ref LIKE 'TRACKB-%');
DELETE FROM ap_payment WHERE payment_ref LIKE 'TRACKB-%';
DELETE FROM vendor_bill WHERE bill_number LIKE 'TRACKB-%';
DELETE FROM ap_vendor WHERE vendor_number LIKE 'TRACKB-%';
COMMIT;

-- row-count summary (printed by apply_seed.sh)
SELECT 'ext_invoice' AS seeded_table, count(*) AS seeded_rows FROM ext_invoice WHERE invoice_number LIKE 'TRACKB-%'
UNION ALL
SELECT 'receivable_payment' AS seeded_table, count(*) AS seeded_rows FROM receivable_payment WHERE created_by = 'trackb-seed'
UNION ALL
SELECT 'payment_application' AS seeded_table, count(*) AS seeded_rows FROM payment_application WHERE application_request_id LIKE 'TRACKB-%'
UNION ALL
SELECT 'payment_application_reversal' AS seeded_table, count(*) AS seeded_rows FROM payment_application_reversal WHERE reversed_by = 'trackb-seed'
UNION ALL
SELECT 'ext_invoice_payment_reversal' AS seeded_table, count(*) AS seeded_rows FROM ext_invoice_payment_reversal WHERE refund_id = 'f5aa4bd1-fbb3-57a0-8a6d-4407998a6ee6'
UNION ALL
SELECT 'ext_invoice_deposit_credit_application' AS seeded_table, count(*) AS seeded_rows FROM ext_invoice_deposit_credit_application WHERE application_id = '4df39a52-c78a-596e-8942-8e2a98924635'
UNION ALL
SELECT 'credit_memo' AS seeded_table, count(*) AS seeded_rows FROM credit_memo WHERE created_by_user_id = 'trackb-seed'
UNION ALL
SELECT 'customer_credit' AS seeded_table, count(*) AS seeded_rows FROM customer_credit WHERE created_by = 'trackb-seed'
UNION ALL
SELECT 'customer_credit_transaction' AS seeded_table, count(*) AS seeded_rows FROM customer_credit_transaction WHERE request_id LIKE 'TRACKB-%'
UNION ALL
SELECT 'ap_vendor' AS seeded_table, count(*) AS seeded_rows FROM ap_vendor WHERE vendor_number LIKE 'TRACKB-%'
UNION ALL
SELECT 'vendor_bill' AS seeded_table, count(*) AS seeded_rows FROM vendor_bill WHERE bill_number LIKE 'TRACKB-%'
UNION ALL
SELECT 'ap_payment' AS seeded_table, count(*) AS seeded_rows FROM ap_payment WHERE payment_ref LIKE 'TRACKB-%'
UNION ALL
SELECT 'ap_payment_allocation' AS seeded_table, count(*) AS seeded_rows FROM ap_payment_allocation WHERE payment_id IN (SELECT payment_id FROM ap_payment WHERE payment_ref LIKE 'TRACKB-%')
ORDER BY seeded_table;
